<script setup lang="ts">
import Dialog from 'primevue/dialog'; import {useAcademyDonations,type AcademyDonation} from '~/composables/useAcademyDonations'; import {storeToRefs} from 'pinia'
const props=defineProps<{visible:boolean;academyId:number;academyName:string;academyOwnerId:number}>(); const emit=defineEmits<{ 'update:visible':[boolean]; donated:[AcademyDonation] }>(); const {user}=storeToRefs(useAuthStore()); const {sendPointDonation,sendCashDonation}=useAcademyDonations(); const step=ref(1), type=ref<'point'|'cash'>('point'), points=ref(1), cash=ref<number|null>(null), purpose=ref(''), anonymous=ref(false), displayName=ref(''), paymentMethod=ref('bank_transfer'), reference=ref(''), slip=ref<File|null>(null), loading=ref(false), error=ref(''), result=ref<AcademyDonation|null>(null), key=ref('')
watch(()=>props.visible,v=>{if(v){step.value=1;result.value=null;error.value='';key.value=crypto.randomUUID()}}); const file=(e:Event)=>{const f=(e.target as HTMLInputElement).files?.[0]; if(f&&f.size<=5*1024*1024)slip.value=f;else error.value='Slip must be an image or PDF up to 5MB.'}; const submit=async()=>{loading.value=true;error.value='';try{let r:any;if(type.value==='point')r=await sendPointDonation(props.academyId,{points_amount:points.value,purpose:purpose.value||undefined,anonymous:anonymous.value,donor_display_name:displayName.value||undefined},key.value);else{const f=new FormData();f.append('cash_amount',String(cash.value||''));if(slip.value)f.append('slip',slip.value);f.append('payment_method',paymentMethod.value);if(reference.value)f.append('payment_reference',reference.value);if(purpose.value)f.append('purpose',purpose.value);f.append('anonymous',String(anonymous.value));if(displayName.value)f.append('donor_display_name',displayName.value);r=await sendCashDonation(props.academyId,f,key.value)}result.value=r.data||r;step.value=5;emit('donated',result.value)}catch(e:any){if(e.status===409){result.value=e.data?.data||e.data?.donation;step.value=5;if(result.value)emit('donated',result.value)}else error.value=e.data?.message||e.message||'Unable to submit donation.'}finally{loading.value=false}}
</script>
<template><Dialog :visible="visible" modal :header="`Support ${academyName}`" class="w-full max-w-lg" @update:visible="emit('update:visible',$event)"><div class="mb-5 flex gap-2"><span v-for="n in 5" :key="n" class="h-2 flex-1 rounded" :class="n<=step?'bg-primary-600':'bg-slate-200'"/></div><div v-if="step===1" class="space-y-3"><h3 class="text-lg font-bold">Choose support type</h3><button v-for="x in [{v:'point',t:'Support with Points'},{v:'cash',t:'Cash donation'}]" :key="x.v" class="w-full rounded-xl border p-4 text-left" @click="type=x.v as any">{{x.t}}</button><button class="w-full rounded-xl bg-primary-600 p-3 text-white" @click="step=2">Next</button></div><div v-else-if="step===2" class="space-y-3"><label v-if="type==='point'">Points<input v-model.number="points" type="number" min="1" step="1" class="w-full rounded border p-2"><small>You have {{user?.points??0}} points. You will support {{academyName}} with {{points}} points.</small></label><template v-else><label>Cash amount<input v-model.number="cash" type="number" min="1" step=".01" class="w-full rounded border p-2"></label><label>Slip<input type="file" accept="image/*,.pdf" @change="file"></label><select v-model="paymentMethod" class="w-full rounded border p-2"><option value="bank_transfer">Bank transfer</option><option value="promptpay">PromptPay</option></select><input v-model="reference" placeholder="Payment reference" class="w-full rounded border p-2"></template><button class="w-full rounded bg-primary-600 p-3 text-white" @click="step=3">Next</button></div><div v-else-if="step===3" class="space-y-3"><textarea v-model="purpose" maxlength="500" placeholder="Purpose" class="w-full rounded border p-2"/><label class="flex gap-2"><input v-model="anonymous" type="checkbox"> Anonymous</label><input v-if="!anonymous" v-model="displayName" placeholder="Display name" class="w-full rounded border p-2"><button class="w-full rounded bg-primary-600 p-3 text-white" @click="step=4">Review</button></div><div v-else-if="step===4" class="space-y-3"><h3 class="font-bold">Review donation</h3><p>{{type==='point'?`${points} points`:`${cash} THB`}} · {{purpose||'No purpose'}}</p><p class="text-red-600">{{error}}</p><button :disabled="loading" class="w-full rounded bg-primary-600 p-3 text-white" @click="submit">{{loading?'Submitting…':'Submit donation'}}</button></div><div v-else class="space-y-3 text-center"><h3 class="text-xl font-bold text-emerald-600">Donation submitted</h3><p>Reference #{{result?.id}}</p><button class="rounded bg-primary-600 px-5 py-3 text-white" @click="emit('update:visible',false)">Close</button></div></Dialog></template>
